 // The My Account endpoint list a visit may open: one column, saved under the connection lock, refused whole when any entry is bad.
 public function test_save_stores_the_endpoint_list_normalised_under_the_lock_and_audits_it(): void {$this->seed(['status'=>'active']);$_POST+=$this->db->rows[0];$_POST['visit_endpoints']=' bulkorder , purchase-lists,bulkorder ';$this->call('save_partner');self::assertSame('success',$GLOBALS['pow_test_transients']['pow_notice_1']['type']);self::assertSame('bulkorder,purchase-lists',$this->registry->find(20)->visit_endpoints);self::assertSame(['bulkorder','purchase-lists'],$this->registry->find(20)->visit_endpoint_list());self::assertStringContainsString('pow_partner_',$this->db->lock_history[0]);self::assertSame(['partner_saved',['visit_endpoints'=>'bulkorder,purchase-lists']],[$this->audit->events[0][0],$this->audit->events[0][1]['detail']]);}
 public function test_save_refuses_a_malformed_endpoint_and_names_it(): void {foreach(['bulkorder,Edit Account','BulkOrder','bulk/order','-lead',['','bulkorder','a,b'],['','Orders']] as $posted){$this->seed(['status'=>'active','visit_endpoints'=>'bulkorder']);$_POST=['partner'=>'20','_wpnonce'=>'valid']+$this->db->rows[0];$_POST['visit_endpoints']=$posted;$label=json_encode($posted);$this->call('save_partner');$notice=$GLOBALS['pow_test_transients']['pow_notice_1'];self::assertSame('error',$notice['type'],$label);self::assertStringContainsString('Not saved, and no other change on the form was kept either',$notice['text']);foreach(array_diff(is_array($posted)?$posted:array_map('trim',explode(',',$posted)),['bulkorder','']) as $bad)self::assertStringContainsString($bad,$notice['text'],$label);self::assertSame([],$this->db->writes,$label);self::assertSame('bulkorder',$this->registry->find(20)->visit_endpoints);self::assertSame([],$this->audit->events);}}
