  $_POST['visit_endpoints']=[''];$this->call('save_partner');self::assertSame('',$this->registry->find(20)->visit_endpoints,'Nothing ticked clears the list');}
 public function test_save_refuses_payment_pages_on_a_punchout_only_connection(): void {foreach([['','dashboard','payment-methods'],['','add-payment-method','set-default-payment-method'],'delete-payment-method'] as $posted){$this->seed(['status'=>'active','visit_endpoints'=>'bulkorder']);$_POST=['partner'=>'20','_wpnonce'=>'valid']+$this->db->rows[0];$_POST['visit_endpoints']=$posted;$this->call('save_partner');$notice=$GLOBALS['pow_test_transients']['pow_notice_1'];self::assertSame('error',$notice['type']);self::assertStringContainsString('never pays on site',$notice['text']);foreach(array_intersect((array)$posted,POW\Account\VisitEndpoints::PAYMENT) as $page)self::assertStringContainsString($page,$notice['text']);self::assertSame([],$this->db->writes);self::assertSame('bulkorder',$this->registry->find(20)->visit_endpoints);}
  $_POST=['partner'=>'0','_wpnonce'=>'valid']+$this->db->rows[0];$_POST['visit_endpoints']=['','payment-methods'];$this->call('save_partner');self::assertStringContainsString('never pays on site',$GLOBALS['pow_test_transients']['pow_notice_1']['text'],'A new connection is punchout-only too');self::assertSame([],$this->db->writes);}
