 /** A new connection opens the dashboard and nothing else until an administrator ticks more; the column default stays '' for any other writer. */
 public function test_a_new_connection_starts_with_the_dashboard_only(): void {$_POST+=$this->db->rows[0];$_POST['partner']='0';$_POST['status']='active';unset($_POST['visit_endpoints']);$this->call('save_partner');self::assertSame('dashboard',$this->registry->find(31)->visit_endpoints,'A connection saved without the field starts with the dashboard');
