 public function test_save_refuses_an_endpoint_list_longer_than_the_column(): void {$this->seed(['status'=>'active']);$_POST+=$this->db->rows[0];$_POST['visit_endpoints']=implode(',',array_map(fn($i)=>'endpoint-'.$i,range(100,130)));$this->call('save_partner');self::assertStringContainsString('must fit in 255',$GLOBALS['pow_test_transients']['pow_notice_1']['text']);self::assertSame([],$this->db->writes);}
 /** A save that fails because schema 8 has not landed says so, instead of blaming the Sender identity. */
 public function test_a_save_failing_for_a_missing_column_names_the_schema_not_the_sender(): void {$this->seed(['status'=>'active']);$_POST+=$this->db->rows[0];$_POST['visit_endpoints']='bulkorder';$this->db->fail_write=true;$this->db->columns=['id','name','status'];$this->call('save_partner');$notice=$GLOBALS['pow_test_transients']['pow_notice_1'];self::assertSame('error',$notice['type']);self::assertStringContainsString('column visit_endpoints is missing',$notice['text']);self::assertStringNotContainsString('Sender identity',$notice['text']);$this->db->columns[]='visit_endpoints';$this->call('save_partner');self::assertStringContainsString('is the Sender identity unique?',$GLOBALS['pow_test_transients']['pow_notice_1']['text'],'With the schema in place the old explanation stands');}
 public function test_a_form_without_the_endpoint_field_keeps_the_saved_list(): void {$this->seed(['status'=>'active','visit_endpoints'=>'bulkorder']);$_POST+=$this->db->rows[0];unset($_POST['visit_endpoints']);$_POST['name']='Renamed Company';$this->call('save_partner');self::assertSame('Renamed Company',$this->registry->find(20)->name);self::assertSame('bulkorder',$this->registry->find(20)->visit_endpoints);self::assertSame([],$this->audit->events[0][1]['detail']);}
 /** WooCommerce's endpoint map as the form reads it: its own pages, the plugin's tab, three pages another plugin added (not in order), and titles for some. */
 private function form_with_endpoints(array $query): string {WC()->query=new class{public function get_query_vars(): array{return ['order-pay'=>'order-pay','order-received'=>'order-received','orders'=>'orders','view-order'=>'view-order','downloads'=>'downloads','edit-account'=>'edit-account','edit-address'=>'my-addresses','payment-methods'=>'payment-methods','lost-password'=>'lost-password','customer-logout'=>'customer-logout','add-payment-method'=>'add-payment-method','delete-payment-method'=>'delete-payment-method','set-default-payment-method'=>'set-default-payment-method','subaccounts'=>'subaccounts','punchout-integration'=>'punchout-integration','bulkorder'=>'bulkorder','purchase-lists'=>'purchase-lists','Bad Name'=>'bad'];}public function get_endpoint_title(string $endpoint,string $action=''): string{if('view-order'===$endpoint)throw new LogicException('view-order has no order on an admin screen');return ['orders'=>'Orders','edit-address'=>'Addresses','payment-methods'=>'Payment methods','bulkorder'=>'<em>Quick</em> order'][$endpoint]??'';}};$GLOBALS['wp_rewrite']=$this->rewrite();return $this->page($query);}
 /** WordPress's rewrite endpoints as a site with WooCommerce, this plugin and another plugin holds them in wp-admin: WooCommerce's by address slug, the other plugin's pages (one of them in no WooCommerce map at all), an API address on every URL, one without a query var, one for posts only and one that could not be stored. */
 private function rewrite(): object {return (object)['endpoints'=>[[8191,'wc/file/transient','wc/file/transient'],[8191,'wc-api','wc-api'],[4096,'orders','orders'],[4096,'view-order','view-order'],[4096,'my-addresses','my-addresses'],[4096,'customer-logout','customer-logout'],[4096,'punchout-integration','punchout-integration'],[4161,'bulkorder','bulkorder'],[4161,'purchase-lists','purchase-lists'],[4161,'new-list','new-list'],[4096,'no-query-var',false],[1,'posts-only','posts-only'],[4096,'Bad/Name','Bad/Name']]];}
 /** @return list<string> The ticked checkbox values, in form order. */
 private function ticked(string $html): array {preg_match_all('#<input type="checkbox" name="visit_endpoints\[\]" value="([^"]+)" checked="checked"#',$html,$m);return $m[1];}
 /** @return list<string> Every checkbox value, in form order. */
 private function rows(string $html): array {preg_match_all('#<input type="checkbox" name="visit_endpoints\[\]" value="([^"]+)"#',$html,$m);return $m[1];}
 private function row(string $html,string $name): string {self::assertSame(1,preg_match('#<li><label><input type="checkbox" name="visit_endpoints\[\]" value="'.preg_quote($name,'#').'".*?</li>#',$html,$m),'No row for '.$name);return $m[0];}
 public function test_edit_form_lists_the_registered_pages_as_checkboxes_grouped_with_notes(): void {$this->seed(['status'=>'active','visit_endpoints'=>'dashboard,bulkorder,late-page,orders']);$html=$this->form_with_endpoints(['action'=>'edit','partner'=>'20']);
  self::assertStringContainsString('My Account pages in a visit',$html);self::assertStringNotContainsString('type="text" class="regular-text" name="visit_endpoints"',$html,'The free-text field is gone');self::assertStringContainsString('<input type="hidden" name="visit_endpoints[]" value="" />',$html,'An all-unticked list still reaches the handler');
  $positions=array_map(fn($h)=>strpos($html,'<strong>'.$h.'</strong>'),['WooCommerce','This plugin','Added by other plugins','Ticked, but not found on this site right now']);self::assertSame(array_filter($positions),$positions,'All four groups render');$sorted=$positions;sort($sorted);self::assertSame($sorted,$positions,'WooCommerce first, then this plugin, then other plugins, then entries not found');
  self::assertSame(['dashboard','orders','downloads','edit-address','payment-methods','add-payment-method','delete-payment-method','set-default-payment-method','edit-account','customer-logout','lost-password','order-pay','order-received','punchout-integration','bulkorder','new-list','purchase-lists','subaccounts','late-page'],$this->rows($html),'Every registered page once, in its group, other plugins alphabetically, a single order folded into Orders; a page only WordPress\'s rewrite endpoints know is offered; an address on every URL, one without a query var, one for posts only and a name that could not be stored are not');
  self::assertSame(['dashboard','orders','bulkorder','late-page'],$this->ticked($html),'The stored list is ticked, including an entry that is not registered right now');
  self::assertStringContainsString('Dashboard <code>/my-account/</code>',$this->row($html,'dashboard'));self::assertStringContainsString('Shows only the pages ticked here.',$this->row($html,'dashboard'));
  self::assertStringContainsString('Orders <code>orders</code>',$this->row($html,'orders'));self::assertStringContainsString('Shows the order list, which every buyer of this connection shares.',$this->row($html,'orders'));self::assertStringContainsString('page stays closed in a visit.',$this->row($html,'orders'));self::assertStringContainsString('Addresses <code>edit-address</code> <span class="description">(address: my-addresses)</span>',$this->row($html,'edit-address'));
  self::assertStringContainsString('Quick order <code>bulkorder</code>',$this->row($html,'bulkorder'),'Another plugin\'s title is used, as text');self::assertStringContainsString('Added by another plugin.',$this->row($html,'bulkorder'));self::assertStringContainsString('Creating users inside a visit is blocked',$html);
  self::assertStringContainsString('<code>new-list</code></label> <span class="description">Added by another plugin.</span>',$this->row($html,'new-list'),'A page known only as a rewrite endpoint is labelled by its name');
  self::assertStringContainsString('Punchout integration <code>punchout-integration</code>',$this->row($html,'punchout-integration'));
  self::assertStringContainsString('Not found on this site right now.',$this->row($html,'late-page'));self::assertStringContainsString('Untick it to remove it.',$this->row($html,'late-page'));self::assertStringNotContainsString('registered with WooCommerce',$html);
  foreach(['downloads'=>'Shared by every buyer','edit-address'=>'from a normal login','edit-account'=>'email address and password'] as $name=>$note){self::assertStringContainsString($note,$this->row($html,$name),$name);self::assertStringNotContainsString('disabled',$this->row($html,$name),$name);}
  foreach(['customer-logout','lost-password','order-pay','order-received','punchout-integration'] as $name){$row=$this->row($html,$name);self::assertStringContainsString(' disabled="disabled"',$row,$name);self::assertStringContainsString('Stays closed in a visit.',$row,$name);self::assertStringNotContainsString('checked',$row,$name);}
  foreach(['pow-endpoint-warning','#d63638','breaks the punchout visit','Exposes this connection','still refuses checkout'] as $gone)self::assertStringNotContainsString($gone,$html,'No red warning for an effect that cannot happen: '.$gone);
  self::assertSame(1,preg_match('#<label>Add a page by name: <input type="text" name="visit_endpoints\[\]" value="" class="regular-text"[^>]*/></label>#',$html),'A name box adds a page the list does not show');self::assertStringContainsString('lowercase letters, digits and hyphens',$html);}
 /** The case that broke on a live store: another plugin adds its pages to WooCommerce's map only on the front end, so wp-admin sees them as rewrite endpoints only. They are offered, ticked or not, so a page unticked once can be ticked again, and a page no source shows can be typed. */
 public function test_a_page_wp_admin_sees_only_as_a_rewrite_endpoint_can_be_unticked_and_ticked_again(): void {$this->seed(['status'=>'active','visit_endpoints'=>'dashboard,bulkorder,purchase-lists,new-list']);WC()->query=new class{public function get_query_vars(): array{return ['orders'=>'orders','view-order'=>'view-order','punchout-integration'=>'punchout-integration'];}public function get_endpoint_title(string $endpoint,string $action=''): string{return '';}};$GLOBALS['wp_rewrite']=(object)['endpoints'=>[[8191,'wc-api','wc-api'],[4096,'orders','orders'],[4096,'view-order','view-order'],[4096,'punchout-integration','punchout-integration'],[4161,'bulkorder','bulkorder'],[4161,'purchase-lists','purchase-lists'],[4161,'new-list','new-list']]];
  $html=$this->page(['action'=>'edit','partner'=>'20']);self::assertSame(['dashboard','orders','punchout-integration','bulkorder','new-list','purchase-lists'],$this->rows($html));self::assertSame(['dashboard','bulkorder','new-list','purchase-lists'],$this->ticked($html));self::assertStringNotContainsString('Ticked, but not found',$html,'Nothing the store registers is called missing');
  $_POST+=$this->db->rows[0];$_POST['visit_endpoints']=['','dashboard','bulkorder','purchase-lists',''];$this->call('save_partner');self::assertSame('dashboard,bulkorder,purchase-lists',$this->registry->find(20)->visit_endpoints,'new-list unticked');
  $html=$this->page(['action'=>'edit','partner'=>'20']);self::assertContains('new-list',$this->rows($html),'The unticked page is still offered');self::assertFalse(in_array('new-list',$this->ticked($html),true),'and shown unticked');
  $_POST['visit_endpoints']=['','dashboard','bulkorder','purchase-lists','new-list',''];$this->call('save_partner');self::assertSame('dashboard,bulkorder,purchase-lists,new-list',$this->registry->find(20)->visit_endpoints,'and ticking it again stores it again');
  unset($GLOBALS['wp_rewrite']);$_POST['visit_endpoints']=['','dashboard','bulkorder','purchase-lists','new-list','typed-page'];$this->call('save_partner');self::assertSame('success',$GLOBALS['pow_test_transients']['pow_notice_1']['type']);self::assertSame('dashboard,bulkorder,purchase-lists,new-list,typed-page',$this->registry->find(20)->visit_endpoints,'A name typed in the box is stored like a ticked box');
  $html=$this->page(['action'=>'edit','partner'=>'20']);self::assertSame(['dashboard','bulkorder','purchase-lists','new-list','typed-page'],$this->ticked($html),'Without any source for them the stored pages keep ticked rows');
  $_POST['visit_endpoints']=['','dashboard','Typed Page'];$this->call('save_partner');$notice=$GLOBALS['pow_test_transients']['pow_notice_1'];self::assertSame('error',$notice['type']);self::assertStringContainsString('Typed Page',$notice['text']);self::assertStringContainsString('type one page name in lowercase letters, digits and hyphens',$notice['text']);self::assertSame('dashboard,bulkorder,purchase-lists,new-list,typed-page',$this->registry->find(20)->visit_endpoints);}
 /** A page a WooCommerce feature adds at run time is WooCommerce's: its account content is defined inside WooCommerce. Anything else stays with the other plugins' pages. */
 public function test_a_page_woocommerce_itself_provides_is_listed_with_woocommerce(): void {if(!defined('WC_ABSPATH'))define('WC_ABSPATH',dirname(__DIR__).'/fixtures/woocommerce-feature/');require_once dirname(__DIR__).'/fixtures/woocommerce-feature/feature-endpoint.php';
  $hook=fn(mixed $function): object=>(object)['callbacks'=>[10=>['x'=>['function'=>$function,'accepted_args'=>1]]]];
  $GLOBALS['wp_filter']=['woocommerce_account_order-withdrawal_endpoint'=>$hook(['POW_Test_Woo_Feature_Endpoint','render']),'woocommerce_account_wishlist_endpoint'=>$hook('pow_test_woo_feature_render'),'woocommerce_account_bulkorder_endpoint'=>$hook(static function(): void {}),'woocommerce_account_offers_endpoint'=>$hook('no_such_function')];
  $this->seed(['status'=>'active','visit_endpoints'=>'dashboard']);WC()->query=new class{public function get_query_vars(): array{return ['orders'=>'orders','view-order'=>'view-order','wishlist'=>'wishlist','order-withdrawal'=>'withdraw-order','bulkorder'=>'bulkorder','offers'=>'offers'];}public function get_endpoint_title(string $endpoint,string $action=''): string{return 'order-withdrawal'===$endpoint?'Withdraw order':'';}};
  $html=$this->page(['action'=>'edit','partner'=>'20']);self::assertSame(['dashboard','orders','order-withdrawal','wishlist','bulkorder','offers'],$this->rows($html),'WooCommerce\'s feature pages follow its standard set; a closure defined elsewhere and a callback that cannot be traced are another plugin\'s');
  self::assertStringContainsString('Withdraw order <code>order-withdrawal</code> <span class="description">(address: withdraw-order)</span></label></li>',$this->row($html,'order-withdrawal'),'No other-plugin note on WooCommerce\'s own page');self::assertStringContainsString('Added by another plugin.',$this->row($html,'bulkorder'));}
 /** Every connection is punchout-only, so the payment-method rows are shown disabled, unticked even when the row names them, with the reason. */
 public function test_payment_rows_are_disabled_on_a_punchout_only_connection(): void {$this->seed(['status'=>'active','visit_endpoints'=>'dashboard,payment-methods']);$html=$this->form_with_endpoints(['action'=>'edit','partner'=>'20']);
  foreach(POW\Account\VisitEndpoints::PAYMENT as $name){$row=$this->row($html,$name);self::assertStringContainsString(' disabled="disabled"',$row,$name);self::assertStringNotContainsString('checked',$row,$name);self::assertStringContainsString('Punchout-only connections never pay on site.',$row,$name);}
  self::assertSame(['dashboard'],$this->ticked($html));self::assertSame(9,substr_count($html,'disabled="disabled"'),'Only the four payment rows and the five pages that never open are disabled');}
 /** Without WooCommerce's endpoint map the form still offers the dashboard and keeps every stored entry. */
 public function test_without_an_endpoint_map_the_form_keeps_the_stored_entries(): void {$this->seed(['status'=>'active','visit_endpoints'=>'bulkorder,orders']);WC()->query=null;$html=$this->page(['action'=>'edit','partner'=>'20']);self::assertSame(['dashboard','bulkorder','orders'],$this->rows($html));self::assertSame(['bulkorder','orders'],$this->ticked($html));self::assertStringNotContainsString('<strong>WooCommerce</strong>',substr($html,strpos($html,'Ticked, but not found on this site right now')));}

